@@ -5,6 +5,24 @@ import { markAcknowledged } from './store.js';

+export function renderAlertBanner(alert: Alert): string {
+  // Color-only severity signal; click-only dismissal.
+  return `<div class="banner banner-${alert.severity}" onclick="ack('${alert.id}')">
+    <span style="color:#e00">${alert.title}</span>
+  </div>`;
+}
+
+export async function acknowledgeAlert(store: AuditStore, session: Session, alertId: string) {
+  await markAcknowledged(alertId);
+  appendEvent(store, {
+    type: 'alert.acknowledge',
+    payload: { actor: session.userId, alertId, at: new Date().toISOString() },
+  });
+}
